I'll create a dedicated `ChatStatusSelector` component with a dropdown and icons, then integrate it into both `ChatViewHeader` and `ChatSidebarNodeExtended`.

## 1. Create ChatStatusSelector Component

```vue src/components/chat/ChatStatusSelector.vue
<script setup>
</script>

<template>
  <div class="flex items-center gap-2">
    <select
      :value="status"
      @change="$emit('status-changed', $event.target.value)"
      :class="[
        'select select-sm select-bordered focus:ring-2 focus:ring-primary/50 pl-8',
        getStatusClass(status)
      ]"
      title="Change chat status"
    >
      <option value="todo">To Do</option>
      <option value="doing">Doing</option>
      <option value="onhold">On Hold</option>
      <option value="done">Done</option>
      <option value="rejected">Rejected</option>
    </select>
    <div class="absolute pl-2 pointer-events-none flex items-center">
      <i :class="getStatusIcon(status)"></i>
    </div>
  </div>
</template>

<script>
export default {
  name: 'ChatStatusSelector',
  props: {
    status: { type: String, required: true }
  },
  emits: ['status-changed'],
  methods: {
    getStatusIcon(status) {
      const statusIcons = {
        'todo': 'fa-solid fa-circle-exclamation text-info',
        'doing': 'fa-solid fa-spinner text-primary',
        'onhold': 'fa-solid fa-pause-circle text-warning',
        'done': 'fa-solid fa-check-circle text-success',
        'rejected': 'fa-solid fa-times-circle text-error'
      }
      return statusIcons[status] || 'fa-solid fa-circle-exclamation text-info'
    },
    getStatusClass(status) {
      const statusClasses = {
        'todo': 'select-info',
        'doing': 'select-primary',
        'onhold': 'select-warning',
        'done': 'select-success',
        'rejected': 'select-error'
      }
      return statusClasses[status] || 'select-info'
    }
  }
}
</script>
```

