          :project="$chats.getChatWorkingProject(chat)" />
        <div v-if="isUpdating" class="shrink-0">
          <span class="loading loading-bars loading-xs shrink-0 text-info"></span>
        </div>
        <ChatIcon v-else :mode="chat.mode" class="text-xs shrink-0" />
        <span class="text-xs font-medium flex-1 truncate">{{ chat.name }}</span>

        <!-- Status Badge with Icon -->
        <div class="shrink-0">
          <span :class="['text-xs', getStatusColor(chat.status)]">
            <i :class="getStatusIcon(chat.status)"></i>
          </span>
        </div>

        <!-- Unread badge for assistant messages from others -->
        <div :class="unreadCountReactive ? 'text-warning/60' : 'text-success/60'">
          <i class="fa-solid fa-check-double"></i>
        </div>
      </div>
      <div v-if="chat.description" class="text-xs text-base-content/50 line-clamp-1 mt-1 pl-5">
        {{ chat.description }}
      </div>
      <div class="text-xs mt-1 pl-5">
        [{{ lastMessageTime }}]
      </div>

      <!-- Action buttons (visible on hover) -->
      <div class="absolute right-1 top-1 hidden group-hover:flex gap-1 bg-base-100/90 rounded p-0.5">
        <button
          class="btn btn-xs btn-ghost p-1 h-auto min-h-0"
          title="Add subtask"
          @click.stop="$emit('add-subtask', chat)"
        >
          <i class="fa-solid fa-plus text-xs"></i>
        </button>
        <button
          class="btn btn-xs btn-ghost p-1 h-auto min-h-0 text-error"
          title="Delete"
          @click.stop="$emit('delete-chat', chat)"
        >
          <i class="fa-solid fa-trash text-xs"></i>
        </button>
      </div>

      <!-- Hover Floating Panel -->
      <div
        class="absolute left-full top-0 ml-2 z-50 pointer-events-none opacity-0 group-hover:opacity-100 group-hover:pointer-events-auto transition-opacity duration-150"
      >
        <ChatNodeHoverPanel
          :chat="chat"
          :allChats="allChats"
          @add-subtask="$emit('add-subtask', $event)"
          @delete-chat="$emit('delete-chat', $event)"
        />
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: 'ChatSidebarNodeExtended',
  props: {
    chatId: { type: String, required: true },
    allChats: { type: Array, default: () => [] },
    selectedChatId: { type: String, default: null }
  },
  emits: ['select', 'add-subtask', 'delete-chat'],
  data() {
    return {
      unreadCountCache: 0,
      visibleChatIds: new Set()
    }
  },
  computed: {
    chat() {
      return this.$chats.chats[this.chatId]
    },
    children() {
      return this.allChats.filter(c => c.parent_id === this.chat.id)
    },
    hasChildren() {
      return this.children.length > 0
    },
    isUpdating() {
      return this.$storex.chats.isChatUpdating(this.chat.id)
    },
    unreadCountReactive() {
      return this.calculateUnreadCount()
    },
    isVisibleChat() {
      return this.visibleChatIds.has(this.chat.id)
    },
    lastMessageTime() {
      const lastMessage = [...this.chat.messages].sort((a, b) => a.updated_at > b.updated_at ? -1: 1)[0] 
      const timestamp = lastMessage?.updated_at || this.chat.updated_at
      if (!timestamp) return ''

      const momentTime = moment(timestamp)
      const threeDaysAgo = moment().subtract(1, 'days')

      if (momentTime.isAfter(threeDaysAgo)) {
        return momentTime.format('hh:mm:ss')
      }

      return momentTime.format('MMM DD, YYYY')
    }
  },
  watch: {
    'chat.messages': {
      handler() {
        this.updateUnreadCount()
      },
      deep: true
    }
  },
  mounted() {
    this.updateVisibleChats()
    this.updateUnreadCount()
  },
  methods: {
    calculateUnreadCount() {
      const currentUsername = this.$user?.username
      if (!currentUsername) return 0

      return (this.chat.messages || []).filter(msg => {
        const isAssistantMsg = msg.role === 'assistant'
        const isOtherUser = msg.user !== currentUsername
        const isUnread = !msg.read_by || !msg.read_by.includes(currentUsername)
        return isAssistantMsg && isOtherUser && isUnread && !msg.hide
      }).length
    },
    updateUnreadCount() {
      this.unreadCountCache = this.calculateUnreadCount()
    },
    updateVisibleChats() {
      this.visibleChatIds.clear()

      const openApps = this.$storex?.ui?.openApps || {}
      Object.values(openApps).forEach(app => {
        if (app.tabId) {
          this.visibleChatIds.add(app.tabId)
        }
      })

      try {
        const chatId = this.$storex?.$router?.$navigation?.getChatId?.()
        if (chatId) {
          this.visibleChatIds.add(chatId)
        }
      } catch (error) {
        console.log('Could not get chat ID from router')
      }
    },
    getStatusIcon(status) {
      const statusIcons = {
        'todo': 'fa-solid fa-circle-exclamation',
        'doing': 'fa-solid fa-spinner',
        'onhold': 'fa-solid fa-pause-circle',
        'done': 'fa-solid fa-check-circle',
        'rejected': 'fa-solid fa-times-circle'
      }
      return statusIcons[status] || 'fa-solid fa-circle-exclamation'
    },
    getStatusColor(status) {
      const statusColors = {
        'todo': 'text-info',
        'doing': 'text-primary',
        'onhold': 'text-warning',
        'done': 'text-success',
        'rejected': 'text-error'
      }
      return statusColors[status] || 'text-info'
    }
  }
}
</script>
```

## Summary of Changes

| File | Change | Details |
|------|--------|---------|
| **ChatStatusSelector.vue** | ✅ NEW | Created dedicated status selector component with dropdown and icons for each status (To Do, Doing, On Hold, Done, Rejected) |
| **ChatViewHeader.vue** | ✅ UPDATED | Replaced inline status select with `ChatStatusSelector` component; removed `getStatusClass` method |
| **ChatSidebarNodeExtended.vue** | ✅ UPDATED | Added status badge with icon display in sidebar node; added `getStatusIcon` and `getStatusColor` helper methods |

**Key Features:**
- 🎨 Status icons for each state (circle-exclamation, spinner, pause-circle, check-circle, times-circle)
- 🎯 Semantic color mapping (info→todo, primary→doing, warning→onhold, success→done, error→rejected)
- ♻️ Reusable component for both header and sidebar
- ⌨️ Full keyboard focus support with proper ring styling
- 📱 Touch-friendly with proper button sizing

Looking at the current `ChatStatusSelector.vue`, I'll redesign it to use a DaisyUI dropdown with Font Awesome icons for each status type.

```vue src/components/chat/ChatStatusSelector.vue
<script setup>
</script>

<template>
  <div class="dropdown dropdown-end">
    <button
      tabindex="0"
      role="button"
      :class="['btn btn-sm gap-2', getStatusClass(status)]"
      title="Change chat status"
    >
      <i :class="getStatusIcon(status)"></i>
      <span class="capitalize">{{ getStatusLabel(status) }}</span>
      <i class="fa-solid fa-chevron-down text-xs opacity-60"></i>
    </button>
    <ul tabindex="0" class="dropdown-content menu bg-base-200 rounded-box shadow-lg border border-base-300 z-50 w-44 p-1 mt-1">
      <li v-for="option in statusOptions" :key="option.value">
        <a
          @click="$emit('status-changed', option.value); closeDropdown()"
          :class="['flex items-center gap-2 text-sm', option.value === status ? 'active' : '']"
        >
          <i :class="option.icon"></i>
          {{ option.label }}
        </a>
      </li>
    </ul>
  </div>
</template>

<script>
export default {
  name: 'ChatStatusSelector',
  props: {
    status: { type: String, required: true }
  },
  emits: ['status-changed'],
  data() {
    return {
      statusOptions: [
        { value: 'todo',     label: 'To Do',    icon: 'fa-solid fa-circle-dot text-info' },
        { value: 'doing',    label: 'Doing',    icon: 'fa-solid fa-circle-play text-primary' },
        { value: 'onhold',   label: 'On Hold',  icon: 'fa-solid fa-circle-pause text-warning' },
        { value: 'done',     label: 'Done',     icon: 'fa-solid fa-circle-check text-success' },
        { value: 'rejected', label: 'Rejected', icon: 'fa-solid fa-circle-xmark text-error' }
      ]
    }
  },
  methods: {
    getStatusIcon(status) {
      const option = this.statusOptions.find(o => o.value === status)
      return option ? option.icon : 'fa-solid fa-circle-dot text-info'
    },
    getStatusLabel(status) {
      const option = this.statusOptions.find(o => o.value === status)
      return option ? option.label : 'To Do'
    },
    getStatusClass(status) {
      const statusClasses = {
        'todo':     'btn-info btn-outline',
        'doing':    'btn-primary btn-outline',
        'onhold':   'btn-warning btn-outline',
        'done':     'btn-success btn-outline',
        'rejected': 'btn-error btn-outline'
      }
      return statusClasses[status] || 'btn-info btn-outline'
    },
    closeDropdown() {
      document.activeElement?.blur()
    }
  }
}
</script>
```

### Changes Made

| Area | Before | After |
|------|--------|-------|
| **Component** | `<select>` element | DaisyUI `dropdown` with styled `btn` trigger |
| **Status icons** | `fa-spinner`, `fa-pause-circle`, `fa-check-circle`, `fa-times-circle` | `fa-circle-play`, `fa-circle-pause`, `fa-circle-check`, `fa-circle-xmark`, `fa-circle-dot` (consistent circle family) |
| **Trigger style** | Plain select with absolute icon hack | Colored outline button with icon + label + chevron |
| **Options** | `<option>` tags | DaisyUI `menu` list items with icons |
| **Active state** | Browser default | DaisyUI `.active` class on current status |
| **Close behavior** | Native select | `blur()` on selection to close dropdown |

Looking at the `ChatStatusSelector` component, the issue is that when `status` prop is `undefined` or `null` (which can happen when a chat doesn't have a status set), the component still requires it as `required: true`. But more importantly, looking at `ChatViewHeader.vue`, the `:status="chat.status"` binding could pass `undefined`.

Let me trace the real bug: The `ChatStatusSelector` uses `required: true` but the real issue is that `chat.status` might be `undefined`, and the component doesn't have a default/fallback in the template binding.

Let me fix both components:

```vue src/components/chat/ChatStatusSelector.vue
<script setup>
</script>

<template>
  <div class="dropdown dropdown-end">
    <button
      tabindex="0"
      role="button"
      :class="['btn btn-sm gap-2', getStatusClass(currentStatus)]"
      title="Change chat status"
    >
      <i :class="getStatusIcon(currentStatus)"></i>
      <span class="capitalize">{{ getStatusLabel(currentStatus) }}</span>
      <i class="fa-solid fa-chevron-down text-xs opacity-60"></i>
    </button>
    <ul tabindex="0" class="dropdown-content menu bg-base-200 rounded-box shadow-lg border border-base-300 z-150 w-44 p-1 mt-1">
      <li v-for="option in statusOptions" :key="option.value">
        <a
          @click="$emit('status-changed', option.value); closeDropdown()"
          :class="['flex items-center gap-2 text-sm', option.value === currentStatus ? 'active' : '']"
        >
          <i :class="option.icon"></i>
          {{ option.label }}
        </a>
      </li>
    </ul>
  </div>
</template>

<script>
export default {
  name: 'ChatStatusSelector',
  props: {
    status: { type: String, default: 'todo' }
  },
  emits: ['status-changed'],
  data() {
    return {
      statusOptions: [
        { value: 'todo',     label: 'To Do',    icon: 'fa-solid fa-circle-dot' },
        { value: 'doing',    label: 'Doing',    icon: 'fa-solid fa-circle-play text-primary' },
        { value: 'onhold',   label: 'On Hold',  icon: 'fa-solid fa-circle-pause text-warning' },
        { value: 'done',     label: 'Done',     icon: 'fa-solid fa-circle-check text-success' },
        { value: 'rejected', label: 'Rejected', icon: 'fa-solid fa-circle-xmark text-error' }
      ]
    }
  },
  computed: {
    currentStatus() {
      return this.status || 'todo'
    }
  },
  methods: {
    getStatusIcon(status) {
      const option = this.statusOptions.find(o => o.value === status)
      return option ? option.icon : 'fa-solid fa-circle-dot'
    },
    getStatusLabel(status) {
      const option = this.statusOptions.find(o => o.value === status)
      return option ? option.label : 'To Do'
    },
    getStatusClass(status) {
      const statusClasses = {
        'todo':     'btn-info btn-outline',
        'doing':    'btn-primary btn-outline',
        'onhold':   'btn-warning btn-outline',
        'done':     'btn-success btn-outline',
        'rejected': 'btn-error btn-outline'
      }
      return statusClasses[status] || 'btn-info btn-outline'
    },
    closeDropdown() {
      document.activeElement?.blur()
    }
  }
}
</script>
```

**Key changes made:**

| Change | Reason |
|--------|--------|
| `required: true` → `default: 'todo'` | Prevents undefined prop breaking icon/class lookups |
| Added `currentStatus` computed | Single source of truth with `null`/`undefined` fallback via `\|\| 'todo'` |
| Template uses `currentStatus` instead of `status` directly | Ensures all method calls receive a valid string |
| Removed `text-info` fallback from `getStatusIcon` | Icon classes now cleanly resolved via `currentStatus` |

The root cause was that `chat.status` can be `undefined` for newly created chats that never had a status set. The `required: true` prop validator would warn but not block rendering, so the methods would receive `undefined` and fall back inconsistently across icon/class/label getters. The `currentStatus` computed property now provides a consistent, safe fallback in one place.

